  assert('minimum fails when below', cache_with_ttl(9, { type: 'number', minimum: 10 }), false);
  assert('maximum passes when met', cache_with_ttl(10, { type: 'number', maximum: 10 }), true);
  assert('maximum passes when below', cache_with_ttl(9, { type: 'number', maximum: 10 }), true);
