  assert('exclusiveMinimum fails when equal', cache_with_ttl(10, { type: 'number', exclusiveMinimum: 10 }), false);
  assert('exclusiveMinimum fails when below', cache_with_ttl(9, { type: 'number', exclusiveMinimum: 10 }), false);
