  assert('items rejects invalid element', cache_with_ttl([2, 0, 6], { type: 'array', items: { type: 'number', minimum: 1 } }), false);
  assert('items validates strings', cache_with_ttl(['a', 'b'], { type: 'array', items: { type: 'string' } }), true);
  assert('tuple items validates by position', cache_with_ttl([1, 'two'], { type: 'array', items: [{ type: 'number' }, { type: 'string' }] }), true);
